ST.xhtml:p:
IF Axis_Z.NcToPlc.AxisState = 9 THEN(*Z轴处于随动状态*)
   IF g_niMotionType = 5  AND g_fZAxisHeight > (g_fParalleBorderHeightM+g_fParalleZFollowHeightM) AND (NOT bOpenEdgeProtectionFlag) THEN(*当前高度大于阶跃高度+随动设置高度（寻到边）*)
     bOpenEdgeProtectionEnable := TRUE;
     bOpenEdgeProtectionFlag := TRUE;
    END_IF;
ELSE
  bOpenEdgeProtectionEnable := FALSE;
  bOpenEdgeProtectionFlag := FALSE;
END_IF;
R_tringEdgeProtectStart(CLK := bOpenEdgeProtectionEnable);
IF R_tringEdgeProtectStart.Q THEN
  bOpenEdgeProtectionEnable := FALSE;
  g_boCNCMoveDisable := TRUE;
END_IF;

F_tringEdgeProtectEnd(CLK := g_bZFollowClose);
IF F_tringEdgeProtectEnd.Q THEN
  g_boCNCMoveDisable := FALSE;
END_IF;



IF g_bPlcResetBuffer THEN
  R_tringEdgeProtectStart(CLK := FALSE);
  bOpenEdgeProtectionEnable := FALSE;
END_IF;
